struct rlimit as_limit;

// Soft limit: 1 GB (1024 * 1024 * 1024)
as_limit.rlim_cur = 1073741824;

// Hard limit: Infinite address space
as_limit.rlim_max = RLIM_INFINITY;

// Set Address Space limit for the process
setrlimit(RLIMIT_AS, &as_limit);

// Example: Lowering the number of open files (soft=10, hard=20)
struct rlimit file_limit = {10, 20};
setrlimit(RLIMIT_NOFILE, &file_limit);
